package com.zully.zulrah;
import com.zully.zulrah.data.ZulrahRotations; import com.zully.zulrah.model.*; import com.zully.zulrah.tracker.*; import org.junit.Test; import static org.junit.Assert.*;
public class EncounterTrackerTest {
 @Test public void documentedRotationsHaveExpectedLengths(){assertEquals(11,ZulrahRotations.byNumber(1).phases().size());assertEquals(11,ZulrahRotations.byNumber(2).phases().size());assertEquals(12,ZulrahRotations.byNumber(3).phases().size());assertEquals(13,ZulrahRotations.byNumber(4).phases().size());}
 @Test public void disambiguatesAtSecondPhase(){RotationDetector d=new RotationDetector();assertEquals(1,d.candidatesAt(1,ZulrahForm.SERPENTINE,ZulrahPosition.EAST).size());assertEquals(3,(int)d.candidatesAt(1,ZulrahForm.SERPENTINE,ZulrahPosition.EAST).iterator().next());assertEquals(4,(int)d.candidatesAt(1,ZulrahForm.TANZANITE,ZulrahPosition.EAST).iterator().next());}
 @Test public void jadAlternatesAndPrays(){EncounterTracker t=new EncounterTracker();t.start(ZulrahForm.SERPENTINE,ZulrahPosition.CENTER);ZulrahRotation r=ZulrahRotations.byNumber(1);for(int i=1;i<=8;i++)t.observePhase(r.phase(i).form(),r.phase(i).position());assertEquals(ZulrahPrayer.PROTECT_FROM_MISSILES,t.currentPrayer());t.attackObserved();assertEquals(ZulrahPrayer.PROTECT_FROM_MAGIC,t.currentPrayer());}
 @Test public void resetClearsEncounter(){EncounterTracker t=new EncounterTracker();t.start(ZulrahForm.SERPENTINE,ZulrahPosition.CENTER);t.reset();assertEquals(EncounterState.Status.INACTIVE,t.state().status());}
 @Test public void eachRotationReplaysAllPhases(){for(ZulrahRotation r:ZulrahRotations.all()){EncounterTracker t=new EncounterTracker();ZulrahPhase first=r.phase(0);t.start(first.form(),first.position());for(int i=1;i<r.phases().size();i++){ZulrahPhase p=r.phase(i);t.observePhase(p.form(),p.position());assertTrue("rotation "+r.number()+" phase "+i,t.state().candidates().contains(r.number()));assertEquals(i,t.state().phaseIndex());}assertEquals((Integer)r.number(),t.rotation());}}
 @Test public void phaseDataPreservesEventsAndPrayers(){ZulrahPhase green=ZulrahRotations.byNumber(1).phase(3);assertTrue(green.events().contains(ZulrahEvent.SNAKELINGS));assertTrue(green.events().contains(ZulrahEvent.VENOM_CLOUDS));assertEquals(ZulrahPrayer.PROTECT_FROM_MISSILES,green.prayer());assertEquals(ZulrahPrayer.PROTECT_FROM_MAGIC,ZulrahRotations.byNumber(2).phase(2).prayer());}
 @Test public void ambiguousUnexpectedObservationIsUncertain(){EncounterTracker t=new EncounterTracker();t.start(ZulrahForm.SERPENTINE,ZulrahPosition.CENTER);t.observePhase(ZulrahForm.SERPENTINE,ZulrahPosition.NORTH);assertEquals(EncounterState.Status.UNCERTAIN,t.state().status());}
 @Test public void nextSpawnPrayerUsesFirstJadPrayer(){EncounterTracker t=new EncounterTracker();ZulrahRotation r=ZulrahRotations.byNumber(3);t.start(r.phase(0).form(),r.phase(0).position());for(int i=1;i<9;i++)t.observePhase(r.phase(i).form(),r.phase(i).position());assertEquals(ZulrahPrayer.PROTECT_FROM_MAGIC,t.nextPhasePrayer());}
}
